// ==============================
// Helpers
// ==============================
function parseDateBR(dateStr) {
  if (!dateStr) return null;

  const [day, month, year] = dateStr.split('/').map(Number);
  return new Date(year, month - 1, day, 0, 0, 0);
}

// ==============================
// Datas do filtro (vindas do agente)
// ==============================
const filtro = $items('Code in JavaScript2')[0]?.json || {};

const dataInicio = parseDateBR(filtro.data_inicio);
const dataFim = parseDateBR(filtro.data_fim);

// Proteção forte
if (!dataInicio || !dataFim) {
  return [];
}

// Ajuste para pegar até o final do dia (23:59:59)
if (filtro.periodo !== 'ultimas_24_horas') {
    dataFim.setHours(23, 59, 59, 999);
}

const tsInicio = dataInicio.getTime();
const tsFim = dataFim.getTime();

// ==============================
// Filtro + normalização
// ==============================
const resultado = [];

for (const item of items) {
  const linha = item.json;
  const dataLinha = parseDateBR(linha.DATA);

  if (!dataLinha) continue;
  const hora = linha.HORA || "00:00";
  const [hr, min] = hora.split(':').map(Number);
  dataLinha.setHours(hr || 0, min || 0, 0, 0);

  const t = dataLinha.getTime();

  if (t >= tsInicio && t <= tsFim) {
    // 🔹 Aqui você entrega o JSON LIMPO
    // Enrich OBS with VOLTAGEM/BATERIA info if present (from alert rows)
    let obsExtra = '';
    if (linha.VOLTAGEM && parseFloat(linha.VOLTAGEM) > 0.1) {
      obsExtra += ` | Tensão: ${linha.VOLTAGEM}V`;
    }
    if (linha.BATERIA && parseFloat(linha.BATERIA) > 0.1) {
      obsExtra += ` | Bat: ${linha.BATERIA}V`;
    }
    if (obsExtra && linha.OBS && !linha.OBS.includes('periódico')) {
      linha.OBS = (linha.OBS || '') + obsExtra;
    }
    resultado.push(linha);
  }
}

// ==============================
// Saída FINAL para o HTML
// ==============================
return [
  {
    json: {
      relatorio: resultado,
      total: resultado.length,
      periodo: {
        inicio: filtro.data_inicio,
        fim: filtro.data_fim
      }
    }
  }
];

let rawOutput = $('AI Agent1').first().json.output;
// Limpa bloco de markdown (```json ... ```) se houver
const codeBlockMatch = rawOutput.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (codeBlockMatch) {
    rawOutput = codeBlockMatch[1];
} else {
    const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) rawOutput = jsonMatch[0];
}

let dados;
try {
  dados = JSON.parse(rawOutput);
} catch (e) {
  return [{ json: { error: "Erro ao interpretar JSON da IA", detalhe: e.message } }];
}

const periodo = dados.periodo;
const valor = dados.valor;

//const now = new Date();
const now = new Date(
  new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' })
);

// ===== Helpers =====
const pad = (n) => String(n).padStart(2, "0");
const formatDate = (d) => {
  if (d instanceof Date && !isNaN(d)) {
    return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;
  }
  return null; // Retorna null se a data for inválida
};
const formatTime = (d) =>
  `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
const cloneDate = (d) => new Date(d.getTime());

// ===== Resultado =====
let result = {
  dispositivo: null,
  hora_inicio: null,
  hora_fim: null,
  data_inicio: null,
  data_fim: null,
};

// ===== Switch determinístico =====
switch (periodo) {
  case "hoje": {
    const d = formatDate(now);
    result.data_inicio = d;
    result.data_fim = d;
    break;
  }
  case "ontem": {
    const d = cloneDate(now);
    d.setDate(d.getDate() - 1);
    const fd = formatDate(d);
    result.data_inicio = fd;
    result.data_fim = fd;
    break;
  }
  case "ultimas_24_horas": {
    const start = cloneDate(now);
    start.setHours(start.getHours() - 24);
    result.data_inicio = formatDate(start);
    result.data_fim = formatDate(now);
    result.hora_inicio = formatTime(start);
    result.hora_fim = formatTime(now);
    break;
  }
  case "ultima_semana": {
    const start = cloneDate(now);
    start.setDate(start.getDate() - 7);
    result.data_inicio = formatDate(start);
    result.data_fim = formatDate(now);
    break;
  }
  case "ultimo_mes": {
    const start = cloneDate(now);
    start.setDate(start.getDate() - 30);
    result.data_inicio = formatDate(start);
    result.data_fim = formatDate(now);
    break;
  }
  case "ultimos_X_dias": {
    if (typeof valor === "number" && valor > 0) {
      const start = cloneDate(now);
      start.setDate(start.getDate() - valor);
      result.data_inicio = formatDate(start);
      result.data_fim = formatDate(now);
    }
    break;
  }
  case "intervalo_datas": {
    // As datas já vêm formatadas como DD/MM/YYYY do classificador
    if (dados.data_inicio) {
      result.data_inicio = dados.data_inicio;
    }
    if (dados.data_fim) {
      result.data_fim = dados.data_fim;
    }
    break;
  }
  case "nenhum":
  default: {
    // Se o usuário não informou mês/ano, assume o mês/ano corrente
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    result.data_inicio = formatDate(start);
    result.data_fim = formatDate(end);
    break;
  }
}

return result;

try {
    const item = $input.first().json;
    const outputRaw = item.intencao;
    const remoteJid = item.remoteJid;

    if (!outputRaw) {
        return { error: "Campo 'intencao' não encontrado ou vazio" };
    }

    if (outputRaw === "BLOQUEADO") {
        return {
            destination: "whatsapp",
            message: item.mensagem_erro || "🚫 Acesso Bloqueado",
            remoteJid: remoteJid
        };
    }

    let dados = item;
    const isAdmin = dados.is_admin === true;

    // === VALIDAÇÃO DE PERMISSÃO (ADMIN) ===
    const comandosLiberados = ["obter_status_atual", "obter_ambiente", "consultar_relatorio", "nenhuma_intencao"];
    if (!isAdmin && dados.intencao && !comandosLiberados.includes(dados.intencao)) {
        return {
            destination: "whatsapp",
            message: "⚠️ *Acesso Negado*\nDesculpe, você não tem permissão de administrador para executar este comando.\n\nVocê pode apenas consultar status e relatórios.",
            remoteJid: remoteJid
        };
    }

    const textoOriginal = dados.parametros?.solicitacao_original?.toLowerCase() || "";

    // ============================
    // FUNÇÃO DE FORMATAÇÃO DE NÚMERO
    // ============================
    function formatarNumero(numOriginal) {
        let num = numOriginal.toString().replace(/\D/g, '');
        if (num.startsWith('55') && num.length >= 12) {
            num = num.substring(2);
        }
        if (num.length === 11) {
            num = num.substring(0, 2) + num.substring(3);
        }
        return '55' + num;
    }

    // === ADICIONAR USUARIO ===
    if (dados.intencao === "adicionar_admin" || dados.intencao === "adicionar_usuario") {

        if (!dados.nivel_acesso) {
            if (textoOriginal.includes("comum") || textoOriginal.includes("usuario") || textoOriginal.includes("usuário")) {
                dados.nivel_acesso = "USER";
            } else if (textoOriginal.includes("admin")) {
                dados.nivel_acesso = "ADMIN";
            }
        }

        if (!dados.novo_numero || !dados.nivel_acesso) {
            return {
                destination: "whatsapp",
                message: "⚠️ Para cadastrar, envie o nível de acesso e o número juntos na mesma mensagem.\n\nExemplo: *Cadastrar o número 81999999999 como usuário comum*",
                remoteJid: remoteJid
            };
        }

        let num_limpo = formatarNumero(dados.novo_numero);
        let role = dados.nivel_acesso.toUpperCase().includes("ADMIN") ? "ADMIN" : "USER";
        let roleLabel = role === "ADMIN" ? "Administrador" : "Usuário comum";

        return {
            destination: "sheets_add_user",
            message: "⏳ *Cadastrando " + roleLabel + "...*\nAdicionando o número " + num_limpo + " ao sistema.",
            remoteJid: remoteJid,
            novo_numero: num_limpo,
            nova_role: role
        };
    }

    // === ALTERAR REGRA DO USUARIO ===
    if (dados.intencao === "alterar_regra_usuario") {
        // Tolerância se a IA extrair nos campos errados (novo_numero em vez de numero_alvo)
        const tgtNum = dados.numero_alvo || dados.novo_numero;
        let tgtLevel = dados.novo_nivel || dados.nivel_acesso;

        if (!tgtLevel) {
            if (textoOriginal.includes("comum") || textoOriginal.includes("usuario") || textoOriginal.includes("usuário")) {
                tgtLevel = "USER";
            } else if (textoOriginal.includes("admin")) {
                tgtLevel = "ADMIN";
            }
        }

        if (!tgtNum || !tgtLevel) {
            return {
                destination: "whatsapp",
                message: "⚠️ Para alterar a regra, envie o número e o novo nível juntos na mesma mensagem.\n\nExemplo: *Alterar o número 81999999999 para admin*",
                remoteJid: remoteJid
            };
        }

        let num_limpo = formatarNumero(tgtNum);
        let novoNivel = tgtLevel.toUpperCase().includes("ADMIN") ? "ADMIN" : "USER";
        let nivelLabel = novoNivel === "ADMIN" ? "Administrador" : "Usuário comum";

        return {
            destination: "sheets_manage_user",
            message: "⏳ *Alterando permissão...*\nAtualizando o número " + num_limpo + " para " + nivelLabel + ".",
            remoteJid: remoteJid,
            numero_alvo: num_limpo,
            novo_nivel: novoNivel,
            operacao: "update"
        };
    }

    // === EXCLUIR USUARIO ===
    if (dados.intencao === "excluir_usuario") {
        const tgtNum = dados.numero_alvo || dados.novo_numero;
        if (!tgtNum) {
            return {
                destination: "whatsapp",
                message: "⚠️ Para excluir, informe o número que deseja remover.\n\nExemplo: *Excluir o número 81999999999*",
                remoteJid: remoteJid
            };
        }

        let num_limpo = formatarNumero(tgtNum);

        return {
            destination: "sheets_manage_user",
            message: "⏳ *Excluindo usuário...*\nRemovendo o número " + num_limpo + " do sistema.",
            remoteJid: remoteJid,
            numero_alvo: num_limpo,
            operacao: "delete"
        };
    }

    // === RESPOSTA NORMALIZADA (MQTT e outros) ===
    let resposta = {
        intencao: dados.intencao || "nenhuma_intencao",
        destination: "mqtt",
        remoteJid: remoteJid,
        is_admin: isAdmin
    };

    if (dados.requer_dados) {
        return {
            destination: "whatsapp",
            message: "Entendi seu pedido de " + dados.intencao.replace('_', ' ') + ", mas preciso de mais detalhes. Qual o valor desejado?",
            remoteJid: remoteJid
        };
    }

    const campos = ["temp_max", "temp_min", "volt_max", "volt_min", "bat_min", "tempo_porta", "nova_tensao", "novo_fator"];
    campos.forEach(c => {
        if (dados[c] !== undefined && dados[c] !== null) resposta[c] = parseFloat(dados[c]);
    });

    return resposta;

} catch (e) {
    return {
        error: "Erro no processamento",
        detalhe: e.message
    };
}

const outputRaw = $input.item.json.output;
const remoteJid = $('Webhook').item.json.body.data.key.remoteJid;

let jsonString = outputRaw;
const codeBlockMatch = outputRaw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (codeBlockMatch) {
