} else {
    const jsonMatch = outputRaw.match(/\{[\s\S]*\}/);
    if (jsonMatch) jsonString = jsonMatch[0];
}

jsonString = jsonString.replace(/[\u0000-\u001F]+/g, "");

let dados;
try {
  dados = JSON.parse(jsonString);
} catch (e) {
  try {
      const clean = jsonString
          .replace(/(['"])?([a-zA-Z0-9_]+)(['"])?:/g, '"$2":') 
          .replace(/'/g, '"'); 
      dados = JSON.parse(clean);
  } catch (e2) {
      return [{
          json: { error: "Falha crítica no parse JSON", intencao: "erro_parse_ia", requer_dados: false }
      }];
  }
}

// === VALIDAÇÃO NA BORDA (GLOBAL) ===
let userRule = "";
let userFound = false;

try {
    const editFieldsNode = $('Edit Fields').first();
    if (editFieldsNode && editFieldsNode.json) {
        if (editFieldsNode.json.RULE !== undefined && editFieldsNode.json.RULE !== null && editFieldsNode.json.RULE !== "") {
            userFound = true;
            userRule = editFieldsNode.json.RULE;
        } else {
            const sheetItems = $('Get row(s) in sheet1').all();
            if (sheetItems && sheetItems.length > 0 && Object.keys(sheetItems[0].json).length > 0 && sheetItems[0].json.NUMERO !== undefined && sheetItems[0].json.NUMERO !== null && sheetItems[0].json.NUMERO !== "") {
               userFound = true;
               userRule = sheetItems[0].json.RULE ? sheetItems[0].json.RULE.toString().trim() : "USER";
            }
        }
    }
} catch(err) {
    userFound = false;
}

if (!userFound) {
    return [{
      json: {
        intencao: "BLOQUEADO",
        mensagem_erro: "🚫 *Acesso Bloqueado*\nDesculpe, seu número não está cadastrado no sistema para acessar este serviço nem para consultar relatórios.",
        is_admin: false
      }
    }];
}

// CORREÇÃO: Garante que userRule não é null e é uma string antes de chamar toUpperCase()
const isAdmin = (userRule && typeof userRule === 'string' && userRule.trim().toUpperCase() === 'ADMIN');

return [
  {
    json: {
      intencao: dados.intencao ? dados.intencao.trim() : null,
      temp_max: dados.temp_max, 
      temp_min: dados.temp_min,
      volt_max: dados.volt_max,
      volt_min: dados.volt_min,
      nova_tensao: dados.nova_tensao,
      novo_fator: dados.novo_fator, 
      bat_min: dados.bat_min,
      tempo_porta: dados.tempo_porta,
      novo_numero: dados.novo_numero,
      nivel_acesso: dados.nivel_acesso,
      numero_alvo: dados.numero_alvo,
      novo_nivel: dados.novo_nivel,
      requer_dados: dados.requer_dados,
      fonte_dados: dados.fonte_dados,
      is_admin: isAdmin,
      parametros: {
        solicitacao_original: dados.parametros ? dados.parametros.solicitacao_original : null,
        detalhe: dados.parametros ? dados.parametros.detalhe : null
      }
    }
  }
];

const todos = $input.all(); // all rows from the sheet

// Get original request data from Code in JavaScript1
const req = $('Code in JavaScript1').first().json;
const rawNumero = req.numero_alvo || '';
const operacao = req.operacao;
const novoNivel = req.novo_nivel;
const remoteJid = req.remoteJid;

function gerarFormatos(num) {
    let n = num.toString().replace(/\D/g, '');
    const set = new Set();
    set.add(n);
    let sem55 = n.startsWith('55') && n.length >= 12 ? n.substring(2) : n;
    set.add(sem55);
    set.add('55' + sem55);
    if (sem55.length === 10) {
        const com9 = sem55.substring(0, 2) + '9' + sem55.substring(2);
        set.add(com9);
        set.add('55' + com9);
    } else if (sem55.length === 11) {
        const sem9 = sem55.substring(0, 2) + sem55.substring(3);
        set.add(sem9);
        set.add('55' + sem9);
    }
    return [...set];
}

const formatos = gerarFormatos(rawNumero);
let encontrado = null;
for (const row of todos) {
    const numNaPlanilha = (row.json.NUMERO || '').toString().trim();
    if (formatos.includes(numNaPlanilha)) {
        encontrado = row.json;
        break;
    }
}

if (!encontrado) {
    return [{
        json: {
            found: false,
            remoteJid: remoteJid,
            message: `⚠️ Número *${rawNumero}* não encontrado no sistema.\n\nVerifique o número e tente novamente.`
        }
    }];
}

return [{
    json: {
        found: true,
        exact_numero: encontrado.NUMERO,
        operacao: operacao,
        novo_nivel: novoNivel,
        remoteJid: remoteJid
    }
}];
